{"file_path":"src/address.js","content":"/**
 * Cell address parsing and column-letter conversion.
 *
 * An address is one or two letters naming a column (A..Z, then AA..ZZ) and
 * one to three digits naming a row of at least 1.
 */

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/** Convert 1-2 letters (A=1) into a column number, 1..702. */
export function colLettersToNum(letters) {
  let n = 0
  for (const ch of letters.toUpperCase()) {
    n = n * 26 + (ch.charCodeAt(0) - 64)
  }
  return n
}

/** Convert a column number, 1..702, back into 1-2 letters. */
export function colNumToLetters(num) {
  let n = num
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

/**
 * Parse a token as a cell address. Returns null when the token is not
 * exactly one or two letters followed by one to three digits naming a row
 * of at least 1 - this covers both malformed tokens and addresses outside
 * the addressable range (AAA1, A1000, A0, FOO and the like).
 */
export function parseAddressToken(token) {
  const m = ADDRESS_RE.exec(token)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  const col = colLettersToNum(letters)
  return { col, row, address: letters + String(row) }
}

/** Build the canonical address string for a column/row pair. */
export function addressFor(col, row) {
  return colNumToLetters(col) + String(row)
}
"}

