{"file_path":"src/values.js","content":"/**
 * Value construction, coercion and comparison for sheet cells. A value is a
 * number, text, a boolean, or an error token.
 */

export function num(value) {
  return { type: 'number', value }
}

export function text(value) {
  return { type: 'text', value }
}

export function bool(value) {
  return { type: 'bool', value }
}

export function err(token) {
  return { type: 'error', value: token }
}

export function isError(v) {
  return v.type === 'error'
}

/**
 * Read a value as a number in an arithmetic position: booleans become 1 or
 * 0, text becomes #VALUE!, and errors pass through unchanged. Returns
 * { num } on success or { err } on failure.
 */
export function toArithNumber(v) {
  if (v.type === 'number') return { num: v.value }
  if (v.type === 'bool') return { num: v.value ? 1 : 0 }
  if (v.type === 'text') return { err: err('#VALUE!') }
  return { err: v }
}

/**
 * Guard an arithmetic result: division by a zero divisor and any other
 * non-finite result both surface as #DIV/0!.
 */
export function finiteOrDiv0(n) {
  return Number.isFinite(n) ? num(n) : err('#DIV/0!')
}

const KIND_RANK = { number: 0, text: 1, bool: 2 }

/**
 * Compare two non-error values: numbers numerically, texts by code point,
 * booleans with false below true, and across kinds every number below
 * every text below every boolean. Returns -1, 0 or 1.
 */
export function compareValues(a, b) {
  const ra = KIND_RANK[a.type]
  const rb = KIND_RANK[b.type]
  if (ra !== rb) return ra < rb ? -1 : 1
  if (a.type === 'bool') {
    const av = a.value ? 1 : 0
    const bv = b.value ? 1 : 0
    return av < bv ? -1 : av > bv ? 1 : 0
  }
  return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
}

const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

/**
 * Parse a literal cell content string (not a formula) into a value: empty
 * text is 0, one of the error tokens is that error, a signed decimal is
 * that number, and anything else is text.
 */
export function parseLiteral(content) {
  if (content === '') return num(0)
  if (ERROR_TOKENS.has(content)) return err(content)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(parseFloat(content))
  return text(content)
}

/** Round to 10 significant digits, then let JavaScript's own formatting apply. */
function roundToSig(x, sig) {
  if (x === 0) return 0
  const neg = x < 0
  const rounded = Number(Math.abs(x).toPrecision(sig))
  return neg ? -rounded : rounded
}

/** Format a value for the `values` command's `<address>=<value>` output. */
export function formatValue(v) {
  switch (v.type) {
    case 'number':
      return String(roundToSig(v.value, 10))
    case 'bool':
      return v.value ? 'TRUE' : 'FALSE'
    case 'error':
      return v.value
    default:
      return v.value
  }
}
"}

