{"file_path":"src/lexer.js","content":"/**
 * Tokenizer for formula bodies (the text after the leading `=`).
 *
 * Returns an array of tokens ending with an EOF token, or null when a
 * character is encountered that no token can start with.
 */
export function tokenize(source) {
  const tokens = []
  const n = source.length
  let i = 0
  while (i < n) {
    const c = source[i]
    if (c === ' ' || c === '\t') {
      i++
      continue
    }
    if (c >= '0' && c <= '9') {
      let j = i + 1
      while (j < n && source[j] >= '0' && source[j] <= '9') j++
      if (source[j] === '.') {
        if (!(j + 1 < n && source[j + 1] >= '0' && source[j + 1] <= '9')) return null
        j++
        while (j < n && source[j] >= '0' && source[j] <= '9') j++
      }
      tokens.push({ type: 'NUMBER', value: source.slice(i, j) })
      i = j
      continue
    }
    if (/[A-Za-z]/.test(c)) {
      let j = i + 1
      while (j < n && /[A-Za-z]/.test(source[j])) j++
      let k = j
      while (k < n && source[k] >= '0' && source[k] <= '9') k++
      tokens.push({ type: 'IDENT', value: source.slice(i, k) })
      i = k
      continue
    }
    if (c === '<') {
      if (source[i + 1] === '=') { tokens.push({ type: 'LE' }); i += 2; continue }
      if (source[i + 1] === '>') { tokens.push({ type: 'NE' }); i += 2; continue }
      tokens.push({ type: 'LT' }); i++; continue
    }
    if (c === '>') {
      if (source[i + 1] === '=') { tokens.push({ type: 'GE' }); i += 2; continue }
      tokens.push({ type: 'GT' }); i++; continue
    }
    if (c === '=') { tokens.push({ type: 'EQ' }); i++; continue }
    if (c === '+') { tokens.push({ type: 'PLUS' }); i++; continue }
    if (c === '-') { tokens.push({ type: 'MINUS' }); i++; continue }
    if (c === '*') { tokens.push({ type: 'STAR' }); i++; continue }
    if (c === '/') { tokens.push({ type: 'SLASH' }); i++; continue }
    if (c === '^') { tokens.push({ type: 'CARET' }); i++; continue }
    if (c === '(') { tokens.push({ type: 'LP' }); i++; continue }
    if (c === ')') { tokens.push({ type: 'RP' }); i++; continue }
    if (c === ',') { tokens.push({ type: 'COMMA' }); i++; continue }
    if (c === ':') { tokens.push({ type: 'COLON' }); i++; continue }
    return null
  }
  tokens.push({ type: 'EOF' })
  return tokens
}
"}

