{"file_path":"src/deps.js","content":"/**
 * Dependency extraction for the `deps` command: every distinct address a
 * formula's parsed syntax tree names directly, ranges expanded, regardless
 * of whether that reference would be semantically valid (a misplaced range
 * still names every cell it covers). Only addresses inside the addressable
 * range are named.
 */
import { parseAddressToken, addressFor } from './address.js'

/** Walk a parsed formula AST and return its named addresses, sorted. */
export function collectDeps(ast) {
  const seen = new Map()

  function addAddress(token) {
    const a = parseAddressToken(token)
    if (a) seen.set(a.address, a)
  }

  function addRange(fromToken, toToken) {
    const a1 = parseAddressToken(fromToken)
    const a2 = parseAddressToken(toToken)
    if (!a1 || !a2) return
    const minCol = Math.min(a1.col, a2.col)
    const maxCol = Math.max(a1.col, a2.col)
    const minRow = Math.min(a1.row, a2.row)
    const maxRow = Math.max(a1.row, a2.row)
    for (let c = minCol; c <= maxCol; c++) {
      for (let r = minRow; r <= maxRow; r++) {
        seen.set(addressFor(c, r), { col: c, row: r })
      }
    }
  }

  function walk(node) {
    switch (node.type) {
      case 'number':
      case 'bool':
        return
      case 'address':
        addAddress(node.token)
        return
      case 'range':
        addRange(node.from, node.to)
        return
      case 'paren':
        walk(node.inner)
        return
      case 'unary':
        walk(node.operand)
        return
      case 'binop':
        walk(node.left)
        walk(node.right)
        return
      case 'call':
        for (const arg of node.args) walk(arg)
        return
      default:
        return
    }
  }

  walk(ast)
  const entries = [...seen.values()]
  entries.sort((a, b) => a.col - b.col || a.row - b.row)
  return entries.map((e) => addressFor(e.col, e.row))
}
"}

