{"file_path":"src/evaluate.js","content":"/**
 * Formula evaluation, with cycle detection across cells.
 */
import { parseAddressToken, addressFor } from './address.js'
import { parseFormula } from './parser.js'
import { num, bool, err, isError, toArithNumber, finiteOrDiv0, compareValues, parseLiteral } from './values.js'

const AGGREGATE_NAMES = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'])

class CycleSignal {
  constructor(addr) {
    this.addr = addr
  }
}

export class EvalContext {
  constructor(cells) {
    this.cells = cells
    this.cache = new Map()
    this.inProgress = new Set()
  }

  /** Evaluate (and cache) the value of a declared or undeclared cell. */
  getValue(addr) {
    if (this.cache.has(addr)) return this.cache.get(addr)
    const cell = this.cells.get(addr)
    if (!cell) {
      const v = num(0)
      this.cache.set(addr, v)
      return v
    }
    if (this.inProgress.has(addr)) throw new CycleSignal(addr)
    this.inProgress.add(addr)
    try {
      const result = this.computeCell(cell)
      this.inProgress.delete(addr)
      this.cache.set(addr, result)
      return result
    } catch (e) {
      if (e instanceof CycleSignal) {
        this.inProgress.delete(addr)
        this.cache.set(addr, err('#CYCLE!'))
        if (e.addr === addr) return err('#CYCLE!')
      }
      throw e
    }
  }

  computeCell(cell) {
    const content = cell.content
    if (content.startsWith('=')) {
      if (!cell.parsed) cell.parsed = parseFormula(content.slice(1))
      if (!cell.parsed.ok) return err('#ERR!')
      return this.evalExpr(cell.parsed.ast)
    }
    return parseLiteral(content)
  }

  /** Evaluate a formula AST node as a single scalar value. */
  evalExpr(node) {
    switch (node.type) {
      case 'number':
        return num(parseFloat(node.value))
      case 'bool':
        return bool(node.value)
      case 'address': {
        const a = parseAddressToken(node.token)
        if (!a) return err('#REF!')
        return this.getValue(a.address)
      }
      case 'range':
        // Grammar-valid, but meaningful only directly as a function
        // argument; anywhere else it is a semantic error.
        return err('#ERR!')
      case 'paren':
        return this.evalExpr(node.inner)
      case 'unary':
        return this.evalUnary(node)
      case 'binop':
        return this.evalBinop(node)
      case 'call':
        return this.evalCall(node)
      default:
        return err('#ERR!')
    }
  }

  evalUnary(node) {
    const v = this.evalExpr(node.operand)
    if (isError(v)) return v
    const c = toArithNumber(v)
    if (c.err) return c.err
    const n = node.op === 'MINUS' ? -c.num : c.num
    return finiteOrDiv0(n)
  }

  evalBinop(node) {
    if (COMPARISON_OPS.has(node.op)) {
      const l = this.evalExpr(node.left)
      if (isError(l)) return l
      const r = this.evalExpr(node.right)
      if (isError(r)) return r
      const cmp = compareValues(l, r)
      return bool(applyCompare(node.op, cmp))
    }
    const l = this.evalExpr(node.left)
    if (isError(l)) return l
    const lc = toArithNumber(l)
    if (lc.err) return lc.err
    const r = this.evalExpr(node.right)
    if (isError(r)) return r
    const rc = toArithNumber(r)
    if (rc.err) return rc.err
    if (node.op === 'SLASH' && rc.num === 0) return err('#DIV/0!')
    let result
    switch (node.op) {
      case 'PLUS':
        result = lc.num + rc.num
        break
      case 'MINUS':
        result = lc.num - rc.num
        break
      case 'STAR':
        result = lc.num * rc.num
        break
      case 'SLASH':
        result = lc.num / rc.num
        break
      case 'CARET':
        result = Math.pow(lc.num, rc.num)
        break
      default:
        result = NaN
    }
    return finiteOrDiv0(result)
  }

  /** Expand an argument node into its ordered list of values: a range
   *  contributes every cell it covers, anything else contributes one. */
  expandArg(node) {
    if (node.type === 'range') return this.expandRange(node)
    return [this.evalExpr(node)]
  }

  expandRange(node) {
    const a1 = parseAddressToken(node.from)
    const a2 = parseAddressToken(node.to)
    if (!a1 || !a2) return [err('#REF!')]
    const minCol = Math.min(a1.col, a2.col)
    const maxCol = Math.max(a1.col, a2.col)
    const minRow = Math.min(a1.row, a2.row)
    const maxRow = Math.max(a1.row, a2.row)
    const values = []
    for (let c = minCol; c <= maxCol; c++) {
      for (let r = minRow; r <= maxRow; r++) {
        values.push(this.getValue(addressFor(c, r)))
      }
    }
    return values
  }

  evalCall(node) {
    const { name, args } = node
    if (AGGREGATE_NAMES.has(name)) return this.evalAggregate(name, args)
    if (name === 'ABS') return this.evalAbs(args)
    if (name === 'IF') return this.evalIf(args)
    return err('#NAME?')
  }

  evalAggregate(name, args) {
    if (args.length < 1) return err('#ERR!')
    const values = []
    for (const a of args) values.push(...this.expandArg(a))

    if (name === 'COUNT') {
      for (const v of values) if (isError(v)) return v
      return num(values.filter((v) => v.type === 'number').length)
    }

    const nums = []
    for (const v of values) {
      const c = isError(v) ? { err: v } : toArithNumber(v)
      if (c.err) return c.err
      nums.push(c.num)
    }
    let result
    if (name === 'SUM') result = nums.reduce((a, b) => a + b, 0)
    else if (name === 'MIN') result = Math.min(...nums)
    else if (name === 'MAX') result = Math.max(...nums)
    else result = nums.reduce((a, b) => a + b, 0) / nums.length // AVG
    return finiteOrDiv0(result)
  }

  evalAbs(args) {
    if (args.length !== 1) return err('#ERR!')
    const values = this.expandArg(args[0])
    let firstNum = null
    for (const v of values) {
      const c = isError(v) ? { err: v } : toArithNumber(v)
      if (c.err) return c.err
      if (firstNum === null) firstNum = c.num
    }
    return finiteOrDiv0(Math.abs(firstNum))
  }

  evalIf(args) {
    if (args.length !== 3) return err('#ERR!')
    const condValues = this.expandArg(args[0])
    let condBool = null
    for (const v of condValues) {
      if (isError(v)) return v
      if (condBool === null) {
        if (v.type === 'bool') condBool = v.value
        else if (v.type === 'number') condBool = v.value !== 0
        else return err('#VALUE!')
      }
    }
    const branch = condBool ? args[1] : args[2]
    const values = this.expandArg(branch)
    return values.length > 0 ? values[0] : err('#ERR!')
  }
}

const COMPARISON_OPS = new Set(['EQ', 'NE', 'LE', 'LT', 'GE', 'GT'])

function applyCompare(op, cmp) {
  switch (op) {
    case 'EQ':
      return cmp === 0
    case 'NE':
      return cmp !== 0
    case 'LT':
      return cmp < 0
    case 'LE':
      return cmp <= 0
    case 'GT':
      return cmp > 0
    case 'GE':
      return cmp >= 0
    default:
      return false
  }
}
"}

