/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */
import { readFileSync } from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { parseFormula } from './parser.js'
import { EvalContext } from './evaluate.js'
import { collectDeps } from './deps.js'
import { formatValue } from './values.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
    fail('usage: cli.js values|deps')
  }

  const input = readFileSync(0, 'utf8')
  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) fail(`line ${e.line}: ${e.message}`)
    throw e
  }

  const addrs = [...cells.keys()].sort((a, b) => {
    const ca = cells.get(a)
    const cb = cells.get(b)
    return ca.col - cb.col || ca.row - cb.row
  })

  const out = []
  if (mode === 'values') {
    const ctx = new EvalContext(cells)
    for (const addr of addrs) {
      out.push(`${addr}=${formatValue(ctx.getValue(addr))}\n`)
    }
  } else {
    for (const addr of addrs) {
      const cell = cells.get(addr)
      let deps = []
      if (cell.content.startsWith('=')) {
        const parsed = parseFormula(cell.content.slice(1))
        if (parsed.ok) deps = collectDeps(parsed.ast)
      }
      out.push(`${addr}:${deps.length ? ' ' + deps.join(' ') : ''}\n`)
    }
  }
  process.stdout.write(out.join(''))
}

main()
"}

